// Build comprehensive debate context for AI analysis
const roomData = $input.first().json;
const requestParams = $('Extract Request Parameters').item.json;

// Extract debate information
const debateContext = {
  topic: roomData.topic || 'Unknown Topic',
  status: roomData.status,
  createdAt: roomData.createdAt,
  completedAt: roomData.completedAt,
  winner: roomData.winner,
  affirmativeScore: roomData.affirmativeScore || 0,
  negativeScore: roomData.negativeScore || 0,
  judgingComplete: roomData.judgingComplete || false,
  // Add debate data from request if provided
  additionalData: requestParams.debateData || {}
};

// Create AI prompt based on analysis type
let systemPrompt = `You are an expert debate analyst for the Arena debate platform. Your role is to provide insightful, balanced analysis of debates.`;

let userPrompt = '';

switch(requestParams.analysisType) {
  case 'summary':
    userPrompt = `Provide a concise summary of this debate:

Topic: ${debateContext.topic}
Winner: ${debateContext.winner || 'No winner yet'}
Affirmative Score: ${debateContext.affirmativeScore}
Negative Score: ${debateContext.negativeScore}
Status: ${debateContext.status}

Provide a 2-3 sentence summary highlighting the key outcome and any notable aspects.`;
    break;

  case 'strengths':
    userPrompt = `Analyze the strengths and weaknesses of both sides in this debate:

Topic: ${debateContext.topic}
Affirmative Score: ${debateContext.affirmativeScore}
Negative Score: ${debateContext.negativeScore}

Provide:
1. Top 3 strengths of the affirmative side
2. Top 3 strengths of the negative side
3. Key weaknesses for each side
4. Areas for improvement`;
    break;

  case 'recommendations':
    userPrompt = `Based on this debate, provide recommendations for future debaters:

Topic: ${debateContext.topic}
Winner: ${debateContext.winner || 'No winner yet'}
Scores - Affirmative: ${debateContext.affirmativeScore}, Negative: ${debateContext.negativeScore}

Provide:
1. Key lessons learned
2. Best practices demonstrated
3. Common pitfalls to avoid
4. Tips for arguing this topic`;
    break;

  default: // 'full' analysis
    userPrompt = `Provide a comprehensive analysis of this debate:

Topic: ${debateContext.topic}
Winner: ${debateContext.winner || 'No winner yet'}
Affirmative Score: ${debateContext.affirmativeScore}
Negative Score: ${debateContext.negativeScore}
Status: ${debateContext.status}
Judging Complete: ${debateContext.judgingComplete}

Provide:
1. Overview of the debate outcome
2. Analysis of why one side won (if applicable)
3. Key arguments and counter-arguments
4. Quality of evidence and reasoning
5. Speaking and persuasion effectiveness
6. Recommendations for participants
7. Overall assessment (rate out of 10)

Format your response in clear sections with markdown.`;
}

return {
  json: {
    systemPrompt: systemPrompt,
    userPrompt: userPrompt,
    debateContext: debateContext,
    roomId: requestParams.roomId
  }
};

// Parse Ollama response and format for Flutter
const ollamaResponse = $input.first().json;
const promptData = $('Build AI Analysis Prompt').item.json;

// Extract AI-generated content
const aiAnalysis = ollamaResponse.message?.content || 'Analysis could not be generated.';

// Format response for Flutter app
return {
  json: {
    success: true,
    roomId: promptData.roomId,
    analysis: aiAnalysis,
    debateContext: promptData.debateContext,
    generatedAt: new Date().toISOString(),
    model: 'qwen3:30b',
    analysisType: $('Extract Request Parameters').item.json.analysisType || 'full'
  }
};
